        <a class="page-link" href="{{ generator(0) }}">&laquo;</a>
    </li>
    {% else %}
    <li class="page-item disabled">
        <a class="page-link" href="javascript:void(0)">&laquo;</a>
    </li>
    {% endif %}
    {% if page > 0 %}
    <li class="page-item">
        <a class="page-link" href="{{ generator(page-1) }}">&lt;</a>
